import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { CostTotals } from '../types'

const totals = atom({ plugin: 'display-cost-bar', key: 'totals' } as const, null)

// One store key per session, so concurrent sessions never overwrite each other.
const SESSION_PREFIX = 'session:'
const KEEP_MONTHS = 13

type Ledger = { accounted: number; days: Record<string, number> }

const pad = (n: number) => String(n).padStart(2, '0')

const dayOf = (ms: number) => {
  const d = new Date(ms)

  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

const usd = (n: number) => `$${n.toFixed(2)}`

const readLedger = async ($: EngineInterface, key: string): Promise<Ledger> => {
  const value = (await $.store.get(key)) as Ledger | undefined

  return value ?? { accounted: 0, days: {} }
}

// Sums every session's ledger into today's and this month's figures, dropping
// sessions that have no day inside the kept window.
const refresh = async ($: EngineInterface) => {
  const now = await $.clock.now()
  const day = dayOf(now)
  const month = day.slice(0, 7)
  const cutoff = new Date(now)
  cutoff.setMonth(cutoff.getMonth() - KEEP_MONTHS)
  const oldest = dayOf(cutoff.getTime())
  let dayUsd = 0
  let monthUsd = 0

  for (const key of await $.store.keys()) {
    if (!key.startsWith(SESSION_PREFIX)) {
      continue
    }

    const ledger = await readLedger($, key)
    const days = Object.keys(ledger.days)

    if (days.every(d => d < oldest)) {
      await $.store.delete(key)
      continue
    }

    for (const d of days) {
      const amount = ledger.days[d] ?? 0

      if (d === day) {
        dayUsd += amount
      }

      if (d.startsWith(month)) {
        monthUsd += amount
      }
    }
  }

  const next: CostTotals = { day, dayUsd, monthUsd }
  await update($, totals, () => next)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await refresh($)

    return result
  })

  on('session.measure', async ($, e, next) => {
    if (e.cost && e.changed.includes('cost')) {
      const key = SESSION_PREFIX + (await $.session.id())
      const ledger = await readLedger($, key)
      // A cost below what was already booked means the session's ledger
      // started over (a resume that kept the id), so all of it is new spend.
      const delta =
        e.cost.usd >= ledger.accounted ? e.cost.usd - ledger.accounted : e.cost.usd

      if (delta > 0) {
        const day = dayOf(await $.clock.now())
        ledger.days[day] = (ledger.days[day] ?? 0) + delta
      }

      ledger.accounted = e.cost.usd
      await $.store.set(key, ledger)
    }

    await refresh($)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const t = await read($, totals)

    if (e.props.hasSurvey || t === null) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box>
        <Text dimColor>Today </Text>
        <Text color="green">{usd(t.dayUsd)}</Text>
        <Text dimColor>  ·  This month </Text>
        <Text color="cyan">{usd(t.monthUsd)}</Text>
      </Box>
    )
  })
}

